use serde_json::Value;use sha2::{Digest,Sha256};use std::fs;
const R:&str="/home/ubuntu/src/zopro-perf-work/key-point-orbits176";
const OLD:&str="/home/ubuntu/src/zopro-perf-work/tool-target/release/deps";
const FROZEN:&str="/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175/frozen/candidate";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let path=format!("{R}/plan.json");let mut s=fs::read_to_string(&path).unwrap();let replacements=[(format!("dependency={OLD}"),format!("dependency={FROZEN}")),(format!("{OLD}/libserde_json-cdebb9338c2784ad.rlib"),format!("{FROZEN}/libserde_json-792a1ccfa9d7a509acedb3e992a9c8158d940f10c0b04abe034fe51f74e5811f.rlib")),(format!("{OLD}/libsha2-16b8f2c03bdf5faa.rlib"),format!("{FROZEN}/libsha2-1c93ccb1b17fec6ca7a76b00c9b7b3dcd3eab11efd897da6dc9ea59c955d7b30.rlib"))];for(a,b)in replacements{assert_eq!(s.matches(&a).count(),2);s=s.replace(&a,&b);}fs::write(path,s).unwrap();let mut pins:Value=serde_json::from_slice(&fs::read(format!("{R}/pins.json")).unwrap()).unwrap();for e in fs::read_dir(FROZEN).unwrap(){let p=e.unwrap().path();if p.is_file(){let p=p.to_str().unwrap();pins[p]=Value::String(hash(p));}}let p=format!("{R}/repair-link.rs");pins[&p]=Value::String(hash(&p));fs::write(format!("{R}/pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();println!("Repaired two tool compiler invocations to use original coherent frozen serde/SHA/transitive libraries with embedded LTO bitcode. No successful compile/test/census existed to repeat.");}
